CREATE TABLE IF NOT EXISTS "admin_classes" (\n  "id" TEXT NOT NULL,\n  "adminId" TEXT NOT NULL,\n  "classId" TEXT NOT NULL,\n  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  CONSTRAINT "admin_classes_pkey" PRIMARY KEY ("id")\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS "admin_classes_adminId_classId_key" ON "admin_classes"("adminId", "classId");\nCREATE INDEX IF NOT EXISTS "admin_classes_classId_idx" ON "admin_classes"("classId");\n\nDO $$\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'admin_classes_adminId_fkey') THEN\n    ALTER TABLE "admin_classes" ADD CONSTRAINT "admin_classes_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "admins"("id") ON DELETE CASCADE ON UPDATE CASCADE;\n  END IF;\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'admin_classes_classId_fkey') THEN\n    ALTER TABLE "admin_classes" ADD CONSTRAINT "admin_classes_classId_fkey" FOREIGN KEY ("classId") REFERENCES "classes"("id") ON DELETE CASCADE ON UPDATE CASCADE;\n  END IF;\nEND $$;\n\nINSERT INTO "admin_classes" ("id", "adminId", "classId")\nSELECT 'adminclass_' || md5(a."id" || ':' || a."classId"), a."id", a."classId" FROM "admins" a WHERE a."classId" IS NOT NULL\nON CONFLICT ("adminId", "classId") DO NOTHING;\n\nINSERT INTO "admin_classes" ("id", "adminId", "classId")\nSELECT 'adminclass_' || md5(a."id" || ':' || c."id"), a."id", c."id" FROM "admins" a JOIN "classes" c ON c."teacherName" = a."fullName" WHERE a."role" = 'teacher'\nON CONFLICT ("adminId", "classId") DO NOTHING;\n